        assert!(content.starts_with("content from thread "));

        // Metadata must be parseable (not corrupted)
        let meta_path = store
            .content_path("http:test", "shared-template")
            .with_extension("meta.json");
        let json = fs::read_to_string(meta_path).unwrap();
        let _: CacheEntry = serde_json::from_str(&json).unwrap();
    }

    #[test]
    fn concurrent_stores_to_different_keys_all_survive() {
        use std::sync::Arc;
        use std::thread;

        let temp = TempDir::new().unwrap();
        let root = Arc::new(temp.path().to_path_buf());

        let mut handles = Vec::new();

        for i in 0..10 {
            let root = Arc::clone(&root);
            handles.push(thread::spawn(move || {
                let store = CacheStore::new(root.as_ref());
                let name = format!("template-{}", i);
                let content = format!("content-{}", i);
                store
                    .store("http:test", &name, &content, 3600)
                    .unwrap();
            }));
        }

        for h in handles {
            h.join().unwrap();
        }

        let store = CacheStore::new(temp.path());
        let entries = store.list().unwrap();
        assert_eq!(entries.len(), 10);

        // Each entry should be loadable with matching content
        for i in 0..10 {
            let name = format!("template-{}", i);
            let expected = format!("content-{}", i);
            let entry = store
                .load("http:test", &name)
                .unwrap()
                .unwrap_or_else(|| panic!("template-{} should exist", i));
            let content = store.read_content(&entry).unwrap();
            assert_eq!(content, expected);
        }
    }
